-- Spectrum Aluminium Sales Analytics | MySQL 8+
-- Synthetic practice data only. Import the CSV into a table named sales_data first.

CREATE DATABASE IF NOT EXISTS spectrum_sales;
USE spectrum_sales;

-- If you create the table manually, use this schema.
CREATE TABLE IF NOT EXISTS sales_data (
    Invoice_ID VARCHAR(30) PRIMARY KEY,
    Invoice_Date DATE NOT NULL,
    Customer_ID VARCHAR(20),
    Customer_Name VARCHAR(120),
    Customer_Segment VARCHAR(40),
    City VARCHAR(60),
    Product_Name VARCHAR(120),
    Product_Category VARCHAR(40),
    Unit VARCHAR(20),
    Quantity INT,
    Unit_Price_SAR DECIMAL(12,2),
    Discount_Percent DECIMAL(5,2),
    Sales_Revenue_SAR DECIMAL(14,2),
    Unit_Cost_SAR DECIMAL(12,2),
    Total_Cost_SAR DECIMAL(14,2),
    Gross_Profit_SAR DECIMAL(14,2),
    Gross_Margin_Percent DECIMAL(6,2),
    Payment_Method VARCHAR(40),
    Payment_Status VARCHAR(20),
    Sales_Representative VARCHAR(80),
    Sales_Channel VARCHAR(40)
);

