-- 0. Validate imported data
SELECT COUNT(*) AS transaction_count,
       MIN(Invoice_Date) AS first_date,
       MAX(Invoice_Date) AS last_date,
       SUM(Sales_Revenue_SAR) AS total_revenue_sar,
       SUM(Gross_Profit_SAR) AS total_gross_profit_sar
FROM sales_data;

-- 1. Which month had the highest sales revenue?
SELECT DATE_FORMAT(Invoice_Date, '%Y-%m') AS sales_month,
       ROUND(SUM(Sales_Revenue_SAR), 2) AS sales_revenue_sar
FROM sales_data
GROUP BY DATE_FORMAT(Invoice_Date, '%Y-%m')
ORDER BY sales_revenue_sar DESC
LIMIT 1;

-- 2. Which product generated the most revenue?
SELECT Product_Name, ROUND(SUM(Sales_Revenue_SAR), 2) AS revenue_sar
FROM sales_data
GROUP BY Product_Name
ORDER BY revenue_sar DESC
LIMIT 1;

-- 3. Which city contributed the most sales?
SELECT City, ROUND(SUM(Sales_Revenue_SAR), 2) AS revenue_sar
FROM sales_data
GROUP BY City
ORDER BY revenue_sar DESC
LIMIT 1;

-- 4. Which product generated the highest gross profit?
SELECT Product_Name, ROUND(SUM(Gross_Profit_SAR), 2) AS gross_profit_sar
FROM sales_data
GROUP BY Product_Name
ORDER BY gross_profit_sar DESC
LIMIT 1;

-- 5. Which product category had the highest gross margin?
-- Weighted margin = total profit / total revenue; avoid averaging row-level percentages.
SELECT Product_Category,
       ROUND(SUM(Gross_Profit_SAR) / NULLIF(SUM(Sales_Revenue_SAR), 0) * 100, 2) AS gross_margin_pct
FROM sales_data
GROUP BY Product_Category
ORDER BY gross_margin_pct DESC
LIMIT 1;

-- 6. Do larger discounts reduce profitability?
-- Interpret as association, not proof of causation. Compare margin and profit by discount level.
SELECT Discount_Percent,
       COUNT(*) AS transactions,
       ROUND(SUM(Sales_Revenue_SAR), 2) AS revenue_sar,
       ROUND(SUM(Gross_Profit_SAR), 2) AS gross_profit_sar,
       ROUND(SUM(Gross_Profit_SAR) / NULLIF(SUM(Sales_Revenue_SAR), 0) * 100, 2) AS gross_margin_pct
FROM sales_data
GROUP BY Discount_Percent
ORDER BY Discount_Percent;

-- Optional: compare discount groups (0-3%, 4-7%, 8%+)
SELECT CASE
         WHEN Discount_Percent <= 3 THEN '0-3%'
         WHEN Discount_Percent <= 7 THEN '4-7%'
         ELSE '8%+'
       END AS discount_band,
       COUNT(*) AS transactions,
       ROUND(SUM(Sales_Revenue_SAR), 2) AS revenue_sar,
       ROUND(SUM(Gross_Profit_SAR), 2) AS gross_profit_sar,
       ROUND(SUM(Gross_Profit_SAR) / NULLIF(SUM(Sales_Revenue_SAR), 0) * 100, 2) AS gross_margin_pct
FROM sales_data
GROUP BY discount_band
ORDER BY MIN(Discount_Percent);

-- 7. Which customer generated the most revenue?
SELECT Customer_ID, Customer_Name,
       ROUND(SUM(Sales_Revenue_SAR), 2) AS revenue_sar
FROM sales_data
GROUP BY Customer_ID, Customer_Name
ORDER BY revenue_sar DESC
LIMIT 1;

-- 8. Which customer segment contributes the most gross profit?
SELECT Customer_Segment,
       ROUND(SUM(Gross_Profit_SAR), 2) AS gross_profit_sar
FROM sales_data
GROUP BY Customer_Segment
ORDER BY gross_profit_sar DESC
LIMIT 1;

-- 9. Top 10 customers by sales
SELECT Customer_ID, Customer_Name,
       ROUND(SUM(Sales_Revenue_SAR), 2) AS revenue_sar,
       ROUND(SUM(Gross_Profit_SAR), 2) AS gross_profit_sar,
       COUNT(DISTINCT Invoice_ID) AS invoice_count
FROM sales_data
GROUP BY Customer_ID, Customer_Name
ORDER BY revenue_sar DESC
LIMIT 10;

-- 10. How much revenue is associated with overdue invoices?
SELECT COUNT(DISTINCT Invoice_ID) AS overdue_invoice_count,
       ROUND(SUM(Sales_Revenue_SAR), 2) AS overdue_revenue_sar
FROM sales_data
WHERE LOWER(TRIM(Payment_Status)) = 'overdue';

-- 11. Which sales representative performs best? Revenue-based ranking.
SELECT Sales_Representative,
       ROUND(SUM(Sales_Revenue_SAR), 2) AS revenue_sar,
       ROUND(SUM(Gross_Profit_SAR), 2) AS gross_profit_sar,
       COUNT(DISTINCT Invoice_ID) AS invoice_count
FROM sales_data
GROUP BY Sales_Representative
ORDER BY revenue_sar DESC;

-- 12. Which sales channel generates the most revenue?
SELECT Sales_Channel,
       ROUND(SUM(Sales_Revenue_SAR), 2) AS revenue_sar,
       ROUND(SUM(Gross_Profit_SAR), 2) AS gross_profit_sar
FROM sales_data
GROUP BY Sales_Channel
ORDER BY revenue_sar DESC;

-- Extra: KPI snapshot
SELECT COUNT(DISTINCT Invoice_ID) AS total_invoices,
       ROUND(SUM(Sales_Revenue_SAR), 2) AS total_revenue_sar,
       ROUND(SUM(Gross_Profit_SAR), 2) AS total_gross_profit_sar,
       ROUND(SUM(Gross_Profit_SAR) / NULLIF(SUM(Sales_Revenue_SAR), 0) * 100, 2) AS overall_gross_margin_pct,
       SUM(Quantity) AS total_quantity
FROM sales_data;
